export interface NginxConfig {
  projectName: string;
  frontendPort: number;
  backendPort: number;
  httpsPort: number;
  serverName?: string;
  certPath?: string;
  keyPath?: string;
}

export function generateNginxConfig(config: NginxConfig): string {
  const {
    projectName,
    frontendPort,
    backendPort,
    httpsPort,
    serverName = '_',
    certPath = `/etc/nginx/ssl/${projectName}.crt`,
    keyPath = `/etc/nginx/ssl/${projectName}.key`,
  } = config;

  return `# Nginx config for ${projectName}
# Generated by Cobra Commander Intake Agent

server {
    listen ${httpsPort} ssl;
    server_name ${serverName};

    ssl_certificate ${certPath};
    ssl_certificate_key ${keyPath};
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;

    location /api/ {
        proxy_pass http://127.0.0.1:${backendPort}/api/;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 300s;
    }

    location /ws/ {
        proxy_pass http://127.0.0.1:${backendPort}/ws/;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_read_timeout 86400s;
    }

    location / {
        proxy_pass http://127.0.0.1:${frontendPort}/;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
`;
}

export function generateSelfSignedCertCommand(projectName: string, certDir = '/etc/nginx/ssl'): string {
  return `mkdir -p ${certDir} && openssl req -x509 -nodes -days 365 -newkey rsa:2048 \\
  -keyout ${certDir}/${projectName}.key \\
  -out ${certDir}/${projectName}.crt \\
  -subj "/CN=${projectName}/O=CobraCommander"`;
}
